In the bang-bang line follower, yon = +1 means turn left and -1 means turn right. What does this code print when it runs?

```
void setup() {
  Serial.begin(9600);
  bool gor[5] = {false, false, false, true, true};
  int yon;
  if (gor[0] || gor[1]) yon = 1;
  else if (gor[3] || gor[4]) yon = -1;
  else yon = 0;
  int sol = constrain(255 - yon * 200, -255, 255);
  int sag = constrain(255 + yon * 200, -255, 255);
  Serial.print("sol=");
  Serial.print(sol);
  Serial.print(" sag=");
  Serial.println(sag);
}
void loop() {}
```

